window.YHH_DIALOG_TEMPLATES = {
  "enquiryDialog":  "<dialog id=\"enquiryDialog\">\n    <div class=\"modal-body modal-body-large\">\n      <button type=\"button\" class=\"modal-close-btn\" data-modal-close aria-label=\"Close dialog\">&times;</button>\n      <div class=\"modal-header\">\n        <div>\n          <h3>Get in touch</h3>\n          <p class=\"modal-subtext\">Send a note and we will reply. To pick a time, <a href=\"https://calendar.google.com/calendar/u/0/appointments/schedules/AcZssZ2_cMxdfUojr153utSiTOByBuvddRpqBLdrqxksB8MPqO4UYEFzoJAKf0pyiJb2e_fZn0DvDBsC\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"gcal-intro-link\" id=\"enquiry-gcal-btn\">book a call</a>.</p>\n        </div>\n      </div>\n\n      <form id=\"intro-call-form\" class=\"lead-form enquiry-form\">\n        <div class=\"form-row\">\n          <div class=\"input-group\">\n            <label for=\"intro_first_name\">First name</label>\n            <input type=\"text\" id=\"intro_first_name\" name=\"Name_First\" autocomplete=\"given-name\" required>\n          </div>\n          <div class=\"input-group\">\n            <label for=\"intro_last_name\">Last name</label>\n            <input type=\"text\" id=\"intro_last_name\" name=\"Name_Last\" autocomplete=\"family-name\" required>\n          </div>\n        </div>\n        <div class=\"form-row\">\n          <div class=\"input-group\">\n            <label for=\"intro_email\">Email</label>\n            <input type=\"email\" id=\"intro_email\" name=\"Email\" autocomplete=\"email\" required>\n          </div>\n          <div class=\"input-group\">\n            <label for=\"intro_phone\">Phone</label>\n            <input type=\"tel\" id=\"intro_phone\" name=\"PhoneNumber\" autocomplete=\"tel\" required>\n          </div>\n        </div>\n        <div class=\"form-row\">\n          <div class=\"input-group\">\n            <label for=\"intro_city\">City</label>\n            <select id=\"intro_city\" name=\"Dropdown\" required>\n              <option value=\"\" disabled selected>Choose a city</option>\n              <option value=\"Melbourne\">Melbourne</option>\n              <option value=\"Brisbane\">Brisbane</option>\n              <option value=\"Canberra\">Canberra</option>\n              <option value=\"Adelaide\">Adelaide</option>\n              <option value=\"Other\">Somewhere else</option>\n            </select>\n          </div>\n          <div class=\"input-group\">\n            <label for=\"intro_service\">What do you need?</label>\n            <select id=\"intro_service\" name=\"service_interest\">\n              <option value=\"Full Service\">A full search</option>\n              <option value=\"Property Inspection\">An inspection</option>\n              <option value=\"Tenancy Consultation\">A consultation</option>\n              <option value=\"General Discovery\">Not sure yet</option>\n            </select>\n          </div>\n        </div>\n        <div class=\"input-group\">\n          <label for=\"intro_notes\">About your search</label>\n          <textarea id=\"intro_notes\" name=\"notes\" rows=\"3\" placeholder=\"Move date, suburbs, and what you need.\"></textarea>\n        </div>\n        <div class=\"form-privacy-block\">\n          <p class=\"form-collection-notice\">\n            <small>YHH Pty Ltd (Your Home Hunter) collects personal information to respond to your enquiry and discuss rental advocacy services. Details are handled under the <em>Privacy Act 1988</em> (Cth) and Australian Privacy Principles. Read our <button type=\"button\" class=\"link-style\" data-modal-target=\"collectionNoticeModal\">Privacy Collection Notice</button> (APP&nbsp;5) and <button type=\"button\" class=\"link-style\" data-modal-target=\"privacyDialog\">Privacy Policy</button>. We never sell your data.</small>\n          </p>\n          <label class=\"privacy-consent-label\">\n            <input type=\"checkbox\" name=\"privacyConsent\" class=\"privacy-consent-checkbox\" value=\"yes\" required>\n            <span>I have read the Privacy Collection Notice and Privacy Policy</span>\n          </label>\n        </div>\n        <button type=\"submit\" class=\"btn btn-primary btn-block\">Send message</button>\n        <p id=\"intro-form-status\" class=\"enquiry-form-status\"></p>\n      </form>\n\n      <p class=\"enquiry-alt\">Or call <a href=\"tel:1800666944\">1800 666 944</a>.</p>\n    </div>\n  </dialog>",
  "fullServiceDetailsModal":  "<dialog id=\"fullServiceDetailsModal\">\n    <div class=\"dialog-body\">\n      <button type=\"button\" class=\"modal-close-btn\" data-modal-close aria-label=\"Close dialog\">&times;</button>\n      <header>\n        <span class=\"tier-label\">End-to-End Concierge Relocation</span>\n        <h2>Full Service Rental Representation</h2>\n        <div class=\"service-meta-box\">\n          <div class=\"service-meta-grid\">\n            <div class=\"service-meta-item\">\n              <strong>Service Scope</strong>\n              Complete Search to Key Handover\n            </div>\n            <div class=\"service-meta-item\">\n              <strong>Investment</strong>\n              Bespoke Quote (Confidential &amp; Obligation-Free)\n            </div>\n            <div class=\"service-meta-item\">\n              <strong>Coverage</strong>\n              Melbourne, Brisbane, Adelaide &amp; Canberra\n            </div>\n            <div class=\"service-meta-item\">\n              <strong>Recommended Timing</strong>\n              At least 4 weeks prior to lease start\n            </div>\n          </div>\n        </div>\n      </header>\n      <main>\n        <section>\n          <h3>Want to take the stress out of finding the perfect rental property to call home?</h3>\n          <p>\n            We can manage every step of the search process for you, from working through your wish list, to live video inspections, to applying via the on-line portals, to reviewing the lease. This service includes:\n          </p>\n        </section>\n\n        <section>\n          <h3>The 6-Stage Relocation Process</h3>\n          <div class=\"step-item\">\n            <h4><span class=\"step-number\">1</span> Consultation</h4>\n            <p>We work through your wish list, including any specific requirements (e.g. location, schools, transport, security, etc.)</p>\n          </div>\n          <div class=\"step-item\">\n            <h4><span class=\"step-number\">2</span> Research</h4>\n            <p>We conduct a comprehensive analysis of ON and OFF market properties to identify those that best suit your requirements.</p>\n          </div>\n          <div class=\"step-item\">\n            <h4><span class=\"step-number\">3</span> Inspection</h4>\n            <p>We provide a curated shortlist of properties and arrange to inspect your preferred options with you, or on your behalf, with a live video walk through.</p>\n          </div>\n          <div class=\"step-item\">\n            <h4><span class=\"step-number\">4</span> Application</h4>\n            <p>We prepare your application, submit it on your behalf, via the agents preferred on-line portal and work with the Property Manager to get you approved.</p>\n          </div>\n          <div class=\"step-item\">\n            <h4><span class=\"step-number\">5</span> Review</h4>\n            <p>We review the lease agreement and can negotiate certain terms on your behalf (e.g. start date).</p>\n          </div>\n          <div class=\"step-item\">\n            <h4><span class=\"step-number\">6</span> Acceptance</h4>\n            <p>We are available to answer questions that may arise and offer advice before you move in and throughout your tenancy.</p>\n          </div>\n        </section>\n\n        <section>\n          <p style=\"font-size: 0.9rem; color: var(--text-muted); margin-top: 16px;\">\n            For more information on this service's inclusions and limitations, please see the detailed <button type=\"button\" data-modal-target=\"termsDialog\" style=\"background:none; border:none; color:var(--primary); text-decoration:underline; font:inherit; cursor:pointer; padding:0;\">Terms and Conditions</button>.\n          </p>\n        </section>\n\n        <section style=\"margin-top: 24px;\">\n          <h3>Frequently Asked Questions</h3>\n          <div class=\"faq-accordion-item\" style=\"border: 1px solid var(--border-color); border-radius: 8px; padding: 14px 18px; margin-bottom: 12px; background: var(--bg-card, #fff);\">\n            <h4 style=\"margin: 0 0 6px 0; font-size: 1rem; color: var(--primary);\">Who is this service for?</h4>\n            <p style=\"margin: 0; font-size: 0.92rem; color: var(--text-muted); line-height: 1.55;\">People who have specific requirements, are unable to conduct their own search (e.g. relocating from interstate or overseas), or do not &quot;fit the box&quot; (e.g. have no recent rental history).</p>\n          </div>\n          <div class=\"faq-accordion-item\" style=\"border: 1px solid var(--border-color); border-radius: 8px; padding: 14px 18px; margin-bottom: 12px; background: var(--bg-card, #fff);\">\n            <h4 style=\"margin: 0 0 6px 0; font-size: 1rem; color: var(--primary);\">How much does this service cost?</h4>\n            <p style=\"margin: 0; font-size: 0.92rem; color: var(--text-muted); line-height: 1.55;\">Because every property search is unique, if you are considering our Full Service Package, we recommend contacting us for a confidential, obligation free discussion, of your situation and our fees.</p>\n          </div>\n          <div class=\"faq-accordion-item\" style=\"border: 1px solid var(--border-color); border-radius: 8px; padding: 14px 18px; margin-bottom: 12px; background: var(--bg-card, #fff);\">\n            <h4 style=\"margin: 0 0 6px 0; font-size: 1rem; color: var(--primary);\">How long does this service take?</h4>\n            <p style=\"margin: 0; font-size: 0.92rem; color: var(--text-muted); line-height: 1.55;\">This depends on a number of factors, like your requirements and the state of the rental market. However, as a guide, we recommend clients engage us at least 4 weeks prior to their required lease start date.</p>\n          </div>\n        </section>\n\n        <section style=\"margin-top: 22px;\">\n          <div class=\"quote-card\" style=\"margin-bottom: 0; background: #f8fafc; border-left: 4px solid var(--primary); padding: 18px 20px; border-radius: 8px;\">\n            <div class=\"stars\" style=\"color: #f59e0b; margin-bottom: 8px;\">★★★★★</div>\n            <p class=\"quote\" style=\"font-style: italic; font-size: 0.93rem; color: var(--text-dark, #2d3748); line-height: 1.55; margin-bottom: 12px;\">\n              &quot;Having returned to Australia from being overseas for almost two decades, I found my initial searches in the rental market frustrating and incredibly difficult. Agents not willing to engage, just mindless and endless registrations to view a place and then no further conversation with the agents as to what your wants and needs are, just properties forwarded on which are largely unsuitable... Long and short of it, the better way to do things is to get help and this is where the YHH team come in. The initial engagement process is easy but deeply personalised and it produces results, even in the highly competitive Melbourne rental market. The experience was fantastic and far quicker than I expected. Special thanks to Viviana who did some viewings on my behalf and was knowledgable about some of the developments in around my search area and most of all honest. There was even one viewing via video call where Viviana told me that the property wasn't going to suit my needs, so we moved on swiftly.&quot;\n            </p>\n            <div class=\"quote-author\" style=\"font-size: 0.88rem;\">\n              <strong>TODD</strong> &bull; <span style=\"color: var(--text-muted);\">Overseas Expat Relocation to Melbourne</span>\n            </div>\n          </div>\n        </section>\n      </main>\n      <div class=\"modal-actions\">\n        <button type=\"button\" data-modal-target=\"searchDialog\" class=\"btn btn-primary\">Request a Search</button>\n        <button type=\"button\" data-modal-target=\"enquiryDialog\" class=\"btn btn-outline\">Talk to Us (Obligation-Free)</button>\n        <button type=\"button\" class=\"btn btn-outline\" data-modal-close style=\"margin-left: auto;\">Close</button>\n      </div>\n    </div>\n  </dialog>",
  "inspectionBookingModal":  "<dialog id=\"inspectionBookingModal\">\n    <div class=\"modal-body modal-body-large\">\n      <button type=\"button\" class=\"modal-close-btn\" data-modal-close aria-label=\"Close dialog\">&times;</button>\n      <div class=\"modal-header\">\n        <div>\n          <span class=\"tier-label\">Hands-On Inspection &amp; Shortlist Audit &bull; Paid Upfront</span>\n          <h3>Book Property Review &amp; Inspection</h3>\n          <p class=\"modal-subtext\">Have an independent tenant advocate review your shortlist, attend inspections, stream live walkthroughs, and uncover hidden red flags before you apply.</p>\n        </div>\n      </div>\n\n      <form id=\"inspection-booking-form\" class=\"lead-form\">\n        <!-- Step 1: Package Selection -->\n        <div class=\"input-group\">\n          <label><strong>Select Your Service Package *</strong></label>\n          <div class=\"package-selector-grid\">\n            <label class=\"package-choice-card active\" id=\"pkg-card-single\">\n              <input type=\"radio\" name=\"inspection_package\" value=\"single\" checked style=\"position: absolute; opacity: 0; pointer-events: none;\">\n              <span class=\"package-badge-tag\">Single Inspection</span>\n              <div class=\"package-card-title\">Review &amp; (1) Inspection</div>\n              <div class=\"package-card-price\">$275 AUD <span>inc. GST</span></div>\n              <p class=\"package-card-desc\">Review up to 4 shortlisted properties + 30-min Zoom shortlist review + 1 physical inspection with live video walkthrough &amp; report.</p>\n            </label>\n\n            <label class=\"package-choice-card\" id=\"pkg-card-express\">\n              <input type=\"radio\" name=\"inspection_package\" value=\"express\" style=\"position: absolute; opacity: 0; pointer-events: none;\">\n              <span class=\"package-badge-tag\">Express Package (Popular)</span>\n              <div class=\"package-card-title\">Review &amp; (3) Inspections</div>\n              <div class=\"package-card-price\">$726 AUD <span>inc. GST</span></div>\n              <p class=\"package-card-desc\">Review up to 6 shortlisted properties + 30-min Zoom shortlist review + 3 physical inspections with live video walkthroughs &amp; reports.</p>\n            </label>\n          </div>\n        </div>\n\n        <!-- Optional Extra Inspections -->\n        <div class=\"form-row\" style=\"align-items: center; background: #fff; border: 1px dashed var(--border); border-radius: var(--radius); padding: 12px 16px; margin-bottom: 20px;\">\n          <div style=\"flex: 1;\">\n            <label for=\"extra_inspections\" style=\"margin-bottom: 2px; font-weight: 600; color: var(--primary);\">Need Additional Inspections?</label>\n            <span style=\"font-size: 0.8rem; color: var(--text-muted);\">$220.00 AUD inc. GST per extra property</span>\n          </div>\n          <div style=\"width: 120px;\">\n            <select id=\"extra_inspections\" name=\"extra_inspections\" style=\"padding: 8px 12px; font-size: 0.95rem;\">\n              <option value=\"0\">0 Extra</option>\n              <option value=\"1\">+1 (+$220)</option>\n              <option value=\"2\">+2 (+$440)</option>\n              <option value=\"3\">+3 (+$660)</option>\n            </select>\n          </div>\n        </div>\n\n        <!-- Step 2: Contact Details -->\n        <h4 style=\"font-size: 1.05rem; color: var(--primary); margin: 20px 0 12px; border-bottom: 1px solid var(--border); padding-bottom: 6px;\">1. Client Contact Details</h4>\n        <div class=\"form-row\">\n          <div class=\"input-group\">\n            <label for=\"insp_book_first_name\">First Name *</label>\n            <input type=\"text\" id=\"insp_book_first_name\" name=\"Name_First\" placeholder=\"First Name\" required>\n          </div>\n          <div class=\"input-group\">\n            <label for=\"insp_book_last_name\">Last Name *</label>\n            <input type=\"text\" id=\"insp_book_last_name\" name=\"Name_Last\" placeholder=\"Last Name\" required>\n          </div>\n        </div>\n\n        <div class=\"form-row\">\n          <div class=\"input-group\">\n            <label for=\"insp_book_email\">Email Address *</label>\n            <input type=\"email\" id=\"insp_book_email\" name=\"Email\" placeholder=\"name@domain.com\" required>\n          </div>\n          <div class=\"input-group\">\n            <label for=\"insp_book_phone\">Phone Number *</label>\n            <input type=\"tel\" id=\"insp_book_phone\" name=\"PhoneNumber\" placeholder=\"+61 400 000 000\" required>\n          </div>\n        </div>\n\n        <!-- Preferred Video Call Platform -->\n        <div class=\"input-group\">\n          <label>Preferred Video Call Platform for Review &amp; Live Walkthrough *</label>\n          <div class=\"consult-platform-options\">\n            <label class=\"platform-option\">\n              <input type=\"radio\" name=\"insp_video_platform\" value=\"Zoom\" checked required>\n              <span>Zoom</span>\n            </label>\n            <label class=\"platform-option\">\n              <input type=\"radio\" name=\"insp_video_platform\" value=\"WhatsApp\" required>\n              <span>WhatsApp</span>\n            </label>\n            <label class=\"platform-option\">\n              <input type=\"radio\" name=\"insp_video_platform\" value=\"FaceTime\" required>\n              <span>FaceTime</span>\n            </label>\n          </div>\n        </div>\n\n        <!-- Step 3: Location & Search Criteria -->\n        <h4 style=\"font-size: 1.05rem; color: var(--primary); margin: 24px 0 12px; border-bottom: 1px solid var(--border); padding-bottom: 6px;\">2. Search Location &amp; Home Preferences</h4>\n        <div class=\"form-row\">\n          <div class=\"input-group\">\n            <label for=\"insp_book_city\">Search City *</label>\n            <select id=\"insp_book_city\" name=\"Search_City\" required>\n              <option value=\"\">Select Target City</option>\n              <option value=\"Melbourne\">Melbourne (VIC)</option>\n              <option value=\"Brisbane\">Brisbane (QLD)</option>\n              <option value=\"Canberra\">Canberra (ACT)</option>\n              <option value=\"Adelaide\">Adelaide (SA)</option>\n              <option value=\"Other\">Other Region</option>\n            </select>\n          </div>\n          <div class=\"input-group\">\n            <label for=\"insp_book_suburbs\">Preferred Suburb(s) *</label>\n            <input type=\"text\" id=\"insp_book_suburbs\" name=\"Preferred_Suburbs\" placeholder=\"e.g. Richmond, South Yarra, Hawthorn\" list=\"yhh-au-suburbs-list\" autocomplete=\"address-level2\" required>\n          </div>\n        </div>\n\n        <div class=\"input-group\">\n          <label for=\"insp_book_criteria\">What are the key things you're looking for in your new home? *</label>\n          <textarea id=\"insp_book_criteria\" name=\"Key_Criteria\" rows=\"2\" placeholder=\"e.g. 2 bedrooms, off-street parking, pet-friendly for a dog, quiet street, walking distance to train, good natural light...\" required></textarea>\n        </div>\n\n        <!-- Step 4: Shortlisted Properties -->\n        <div style=\"display: flex; justify-content: space-between; align-items: baseline; margin: 24px 0 12px; border-bottom: 1px solid var(--border); padding-bottom: 6px;\">\n          <h4 style=\"font-size: 1.05rem; color: var(--primary); margin: 0;\">3. Shortlisted Properties to Review &amp; Inspect</h4>\n          <span id=\"shortlist-count-badge\" style=\"font-size: 0.8rem; font-weight: 600; color: var(--accent);\">Up to 4 properties</span>\n        </div>\n        <p class=\"modal-subtext\" style=\"margin-bottom: 14px;\">Provide the addresses and online listing links (realestate.com.au / Domain) for the properties you want our team to audit.</p>\n\n        <!-- Property 1 -->\n        <div class=\"property-item-box\">\n          <div class=\"property-item-header\">\n            <span>Property #1 (Primary)</span>\n            <span style=\"color: #dc2626; font-size: 0.78rem;\">Required *</span>\n          </div>\n          <div class=\"form-row\">\n            <div class=\"input-group\" style=\"margin-bottom: 8px;\">\n              <input type=\"text\" id=\"prop_addr_1\" name=\"Property_1_Address\" placeholder=\"Full street address (e.g. 12/45 Smith St, Richmond)\" data-address-autocomplete=\"true\" autocomplete=\"street-address\" required>\n            </div>\n            <div class=\"input-group\" style=\"margin-bottom: 8px;\">\n              <input type=\"url\" id=\"prop_url_1\" name=\"Property_1_URL\" placeholder=\"Listing link (https://www.realestate.com.au/...)\" required>\n            </div>\n          </div>\n        </div>\n\n        <!-- Property 2 -->\n        <div class=\"property-item-box\">\n          <div class=\"property-item-header\">\n            <span>Property #2</span>\n            <span style=\"color: #dc2626; font-size: 0.78rem;\">Required *</span>\n          </div>\n          <div class=\"form-row\">\n            <div class=\"input-group\" style=\"margin-bottom: 8px;\">\n              <input type=\"text\" id=\"prop_addr_2\" name=\"Property_2_Address\" placeholder=\"Full street address\" data-address-autocomplete=\"true\" autocomplete=\"street-address\" required>\n            </div>\n            <div class=\"input-group\" style=\"margin-bottom: 8px;\">\n              <input type=\"url\" id=\"prop_url_2\" name=\"Property_2_URL\" placeholder=\"Listing link\" required>\n            </div>\n          </div>\n        </div>\n\n        <!-- Property 3 -->\n        <div class=\"property-item-box\">\n          <div class=\"property-item-header\">\n            <span>Property #3</span>\n            <span style=\"color: var(--text-muted); font-size: 0.78rem;\">Optional (Recommended for Shortlist Review)</span>\n          </div>\n          <div class=\"form-row\">\n            <div class=\"input-group\" style=\"margin-bottom: 8px;\">\n              <input type=\"text\" id=\"prop_addr_3\" name=\"Property_3_Address\" placeholder=\"Full street address\" data-address-autocomplete=\"true\" autocomplete=\"street-address\">\n            </div>\n            <div class=\"input-group\" style=\"margin-bottom: 8px;\">\n              <input type=\"url\" id=\"prop_url_3\" name=\"Property_3_URL\" placeholder=\"Listing link\">\n            </div>\n          </div>\n        </div>\n\n        <!-- Property 4 -->\n        <div class=\"property-item-box\">\n          <div class=\"property-item-header\">\n            <span>Property #4</span>\n            <span style=\"color: var(--text-muted); font-size: 0.78rem;\">Optional</span>\n          </div>\n          <div class=\"form-row\">\n            <div class=\"input-group\" style=\"margin-bottom: 8px;\">\n              <input type=\"text\" id=\"prop_addr_4\" name=\"Property_4_Address\" placeholder=\"Full street address\" data-address-autocomplete=\"true\" autocomplete=\"street-address\">\n            </div>\n            <div class=\"input-group\" style=\"margin-bottom: 8px;\">\n              <input type=\"url\" id=\"prop_url_4\" name=\"Property_4_URL\" placeholder=\"Listing link\">\n            </div>\n          </div>\n        </div>\n\n        <!-- Property 5 & 6 (Shown for Express Package) -->\n        <div id=\"express-properties-block\" style=\"display: none;\">\n          <div class=\"property-item-box\">\n            <div class=\"property-item-header\">\n              <span>Property #5 (Express Package)</span>\n              <span style=\"color: var(--text-muted); font-size: 0.78rem;\">Optional</span>\n            </div>\n            <div class=\"form-row\">\n            <div class=\"input-group\" style=\"margin-bottom: 8px;\">\n                <input type=\"text\" id=\"prop_addr_5\" name=\"Property_5_Address\" placeholder=\"Full street address\" data-address-autocomplete=\"true\" autocomplete=\"street-address\">\n              </div>\n              <div class=\"input-group\" style=\"margin-bottom: 8px;\">\n                <input type=\"url\" id=\"prop_url_5\" name=\"Property_5_URL\" placeholder=\"Listing link\">\n              </div>\n            </div>\n          </div>\n\n          <div class=\"property-item-box\">\n            <div class=\"property-item-header\">\n              <span>Property #6 (Express Package)</span>\n              <span style=\"color: var(--text-muted); font-size: 0.78rem;\">Optional</span>\n            </div>\n            <div class=\"form-row\">\n              <div class=\"input-group\" style=\"margin-bottom: 8px;\">\n                <input type=\"text\" id=\"prop_addr_6\" name=\"Property_6_Address\" placeholder=\"Full street address\" data-address-autocomplete=\"true\" autocomplete=\"street-address\">\n              </div>\n              <div class=\"input-group\" style=\"margin-bottom: 8px;\">\n                <input type=\"url\" id=\"prop_url_6\" name=\"Property_6_URL\" placeholder=\"Listing link\">\n              </div>\n            </div>\n          </div>\n        </div>\n\n        <!-- Step 5: Service Agreement & Terms Container -->\n        <div class=\"consult-terms-container\">\n          <h4 class=\"terms-title\">Service Agreement &amp; The Fine Print</h4>\n          <div class=\"terms-scroll-box\">\n            <p><strong>Parties &amp; Purpose:</strong> This Service Agreement is made between Your Home Hunter Pty Ltd (ACN 700 927 000, \"YHH\") and the Client named above. The Client engages YHH to provide independent Property Review &amp; Inspection Services on the terms set out herein.</p>\n            <p><strong>Services Undertaken:</strong> YHH will: (a) take instructions regarding size, amenities, and criteria; (b) undertake a preliminary due diligence review of properties identified by the Client (up to 4 for Single Package, up to 6 for Express Package); (c) provide advice on which property(s) are the best match; (d) arrange for curated properties to be physically inspected on the Client's behalf with a live video walkthrough tour and condition report.</p>\n            <p><strong>Client Acknowledgements:</strong> The Client agrees: (a) While YHH provides guidance and recommendations, the Client is solely responsible for carrying out any tenancy application steps; (b) YHH is neither a lawyer nor accountant and advice is not legal or financial advice; (c) Nothing in this Agreement results in YHH being considered a co-applicant on any tenancy lease.</p>\n            <p><strong>Fees &amp; Invoicing:</strong> Fees are invoiced upon booking review via secure payment link. Minimum 48 hours notice is required between booking and the first physical inspection.</p>\n            <p><strong>Red-Flag Protection Guarantee:</strong> If, based on our preliminary research and due diligence, you choose not to proceed with the physical inspection of a property, a partial refund of $132.00 AUD inc. GST will be provided. This can be refunded or credited toward another property inspection.</p>\n            <p><strong>Limitations of Liability:</strong> To the maximum extent permitted by Australian law, YHH's total liability arising out of or in connection with this Agreement is strictly limited to the aggregate value of Fees paid by the Client. Neither Party will be liable for indirect, incidental, special or consequential losses.</p>\n            <p><strong>Zero Tolerance Policy:</strong> YHH is committed to supporting a culture of respect and well-being for our employees. Rude or abusive behaviour will not be tolerated. YHH reserves the right to terminate an engagement should this occur, with no refund payable.</p>\n            <p><strong>Governing Law &amp; Privacy:</strong> Governed by the laws of the State of Victoria. Personal data is handled in strict accordance with the Australian Privacy Principles (APP) and our Privacy Policy.</p>\n          </div>\n\n          <div class=\"terms-acceptance-box\">\n            <label class=\"terms-checkbox-label\">\n              <input type=\"checkbox\" id=\"insp_terms_accept\" required>\n              <span><strong>I have read and understood the Service Agreement and agree to the Privacy Statement *</strong></span>\n            </label>\n          </div>\n\n          <div class=\"form-row\" style=\"margin-top: 12px;\">\n            <div class=\"input-group\" style=\"margin-bottom: 0;\">\n              <label for=\"insp_signature\">Client Digital Signature (Full Legal Name) *</label>\n              <input type=\"text\" id=\"insp_signature\" placeholder=\"Type your full legal name\" required>\n            </div>\n            <div class=\"input-group\" style=\"margin-bottom: 0;\">\n              <label for=\"insp_agreement_date\">Agreement Date</label>\n              <input type=\"text\" id=\"insp_agreement_date\" value=\"20-Sep-2026\" readonly style=\"background: #f8fafc; color: var(--text-muted);\">\n            </div>\n          </div>\n        </div>\n\n        <!-- Step 6: Upfront Fee Summary Box (Live Calculated) -->\n        <div class=\"consult-fee-box\">\n          <div class=\"fee-row\">\n            <span id=\"fee-package-name\">Property Review &amp; (1) Inspection Package:</span>\n            <span id=\"fee-base-amount\">$275.00 AUD</span>\n          </div>\n          <div class=\"fee-row\" id=\"fee-extra-row\" style=\"display: none;\">\n            <span id=\"fee-extra-label\">Additional Inspections:</span>\n            <span id=\"fee-extra-amount\">$0.00 AUD</span>\n          </div>\n          <div class=\"fee-row total\">\n            <strong>Total payable (inc. GST):</strong>\n            <strong id=\"fee-total-amount\">$275.00 AUD</strong>\n          </div>\n          <p class=\"fee-subtext\">Includes GST. Includes a 30-min Zoom shortlist review call, physical walkthrough, and a $132 inc. GST red-flag cancellation guarantee. A secure payment link and scheduling calendar will be dispatched upon review.</p>\n        </div>\n\n        <div class=\"form-privacy-block\">\n          <p class=\"form-collection-notice\">\n            <small>YHH Pty Ltd (Your Home Hunter) collects personal information to deliver property review and inspection services. Details are handled under the <em>Privacy Act 1988</em> (Cth) and Australian Privacy Principles. Read our <button type=\"button\" class=\"link-style\" data-modal-target=\"collectionNoticeModal\">Privacy Collection Notice</button> (APP&nbsp;5) and <button type=\"button\" class=\"link-style\" data-modal-target=\"privacyDialog\">Privacy Policy</button>. We never sell your data.</small>\n          </p>\n          <label class=\"privacy-consent-label\">\n            <input type=\"checkbox\" name=\"privacyConsent\" class=\"privacy-consent-checkbox\" value=\"yes\" required>\n            <span>I have read and understand the Privacy Collection Notice and Privacy Policy *</span>\n          </label>\n        </div>\n\n        <button type=\"submit\" id=\"insp-submit-btn\" class=\"btn btn-primary btn-block\" style=\"padding: 14px; font-size: 1rem; margin-top: 10px;\">Accept Terms &amp; Book Inspection Review ($275.00 AUD inc. GST) &rarr;</button>\n        <p id=\"insp-booking-form-status\" style=\"font-size: 0.9rem; margin-top: 10px; font-weight: 500; text-align: center;\"></p>\n      </form>\n\n      <!-- Confirmation Screen -->\n      <div id=\"inspection-booking-success-view\" class=\"wishlist-success-view\" style=\"display: none;\">\n        <div class=\"success-icon-badge\">&#10003;</div>\n        <h3>Property Review &amp; Inspection Booked!</h3>\n        <p>Thank you. Your shortlist details and signed service agreement have been received by our tenant advocacy team.</p>\n        <div class=\"success-summary-box\">\n          <p><strong>What Happens Next:</strong></p>\n          <ul style=\"text-align: left; margin: 12px 0 16px 20px; font-size: 0.9rem; color: var(--text-dark);\">\n            <li>Our advocacy team is conducting preliminary due diligence on your submitted property addresses.</li>\n            <li>We will send your invoice payment link and a calendar invite to schedule your 30-minute Zoom shortlist review with your senior advocate.</li>\n            <li>Upon confirmation, our field inspector will be scheduled to attend the viewings and stream your live walkthrough tour.</li>\n          </ul>\n        </div>\n        <div class=\"modal-footer-row\" style=\"display: flex; gap: 12px; justify-content: center; margin-top: 20px;\">\n          <button type=\"button\" class=\"btn btn-primary\" data-modal-close>Done &amp; Close</button>\n        </div>\n      </div>\n\n      <div class=\"modal-footer-row\" style=\"display: flex; justify-content: space-between; align-items: center; margin-top: 16px; padding-top: 14px; border-top: 1px solid var(--border);\">\n        <a href=\"tel:1800666944\" class=\"btn btn-outline btn-sm\">Direct Phone: 1800 666 944</a>\n        <button type=\"button\" class=\"btn btn-outline btn-sm\" data-modal-close>Close</button>\n      </div>\n    </div>\n  </dialog>",
  "inspectionDetailsModal":  "<dialog id=\"inspectionDetailsModal\">\n    <div class=\"dialog-body\">\n      <button type=\"button\" class=\"modal-close-btn\" data-modal-close aria-label=\"Close dialog\">&times;</button>\n      <header>\n        <span class=\"tier-label\">Hands-On Inspection &amp; Reporting</span>\n        <h2>Property Review &amp; Inspection Service</h2>\n        <div class=\"service-meta-box\">\n          <div class=\"service-meta-grid\">\n            <div class=\"service-meta-item\">\n              <strong>Pricing</strong>\n              Single: $275 inc. GST &bull; Express (3-pack): $726 inc. GST\n            </div>\n            <div class=\"service-meta-item\">\n              <strong>Locations</strong>\n              Melbourne, Brisbane, Canberra &amp; Adelaide\n            </div>\n            <div class=\"service-meta-item\">\n              <strong>Booking Policy</strong>\n              Minimum 48 hours notice required\n            </div>\n            <div class=\"service-meta-item\">\n              <strong>Red-Flag Protection</strong>\n              $132 inc. GST partial refund if cancelled after research\n            </div>\n          </div>\n        </div>\n      </header>\n      <main>\n        <section>\n          <h3>Your Unbiased Eyes &amp; Ears On The Ground</h3>\n          <p>\n            Real estate photos, wide-angle lenses, and curated staging frequently disguise poor maintenance, mould, street noise, and layout defects. If you cannot attend inspections in person, our tenant advocates attend on your behalf and deliver an unvarnished assessment of the property.\n          </p>\n        </section>\n\n        <section>\n          <h3>Comprehensive Inspection Inclusions</h3>\n          <div class=\"step-item\">\n            <h4>Pre-Inspection Due Diligence &amp; Listing Audit</h4>\n            <p>Prior to arriving on site, we review the listing history, council zoning, public transport proximity, flight paths, and nearby active construction developments that could impact your quiet enjoyment.</p>\n          </div>\n          <div class=\"step-item\">\n            <h4>Physical Attendance &amp; Live Walkthrough</h4>\n            <p>We physically attend the scheduled open-for-inspection or private viewing. Join us in real time via live video stream (Zoom, WhatsApp, or FaceTime), or receive a high-definition 4K recorded video tour with live commentary.</p>\n          </div>\n          <div class=\"step-item\">\n            <h4>Defect, Condition &amp; Livability Check</h4>\n            <p>We test water pressure and drainage, inspect under-sink cabinetry and ceilings for damp or odour, test window seals and locks, assess storage capacity, examine natural light angles, and inspect heating and cooling systems.</p>\n          </div>\n          <div class=\"step-item\">\n            <h4>Streetscape, Noise &amp; Parking Assessment</h4>\n            <p>We evaluate street safety, traffic noise levels, neighbourhood upkeep, permit parking availability, and proximity to neighbouring buildings or commercial venues.</p>\n          </div>\n          <div class=\"step-item\">\n            <h4>Direct Property Manager Engagement</h4>\n            <p>We speak directly with the leasing agent on site to uncover applicant volume, landlord expectations, preferred move-in dates, and maintenance commitments before you submit.</p>\n          </div>\n        </section>\n\n        <section>\n          <div class=\"notice-callout\">\n            <strong>Clear Red-Flag &amp; Refund Guarantee:</strong> If our preliminary pre-inspection research reveals critical undisclosed red flags (such as major active construction or severe building defects) and you decide not to proceed with the physical inspection, we provide a partial refund of $132 inc. GST. All bookings require a minimum of 48 hours notice.\n          </div>\n        </section>\n      </main>\n      <div class=\"modal-actions\">\n        <button type=\"button\" data-modal-target=\"inspectionBookingModal\" class=\"btn btn-primary\">Book Review &amp; Inspection (From $275 AUD inc. GST)</button>\n        <a href=\"tel:1800666944\" class=\"btn btn-outline\">Call 1800 666 944</a>\n        <button type=\"button\" class=\"btn btn-outline\" data-modal-close style=\"margin-left: auto;\">Close</button>\n      </div>\n    </div>\n  </dialog>",
  "consultBookingModal":  "<dialog id=\"consultBookingModal\">\n    <div class=\"modal-body modal-body-large\">\n      <button type=\"button\" class=\"modal-close-btn\" data-modal-close aria-label=\"Close dialog\">&times;</button>\n      <div class=\"modal-header\">\n        <div>\n          <span class=\"tier-label\">1-on-1 Strategic Advice &bull; Paid Upfront</span>\n          <h3>Book Tenancy Consultation</h3>\n          <p class=\"modal-subtext\">Dedicated 1-on-1 session (60 minutes) with a tenant advocate &bull; Please provide as much detail as possible for discussion during the appointment.</p>\n        </div>\n      </div>\n\n      <form id=\"consult-booking-form\" class=\"lead-form\">\n        <!-- Contact Details -->\n        <div class=\"form-row\">\n          <div class=\"input-group\">\n            <label for=\"consult_first_name\">First Name *</label>\n            <input type=\"text\" id=\"consult_first_name\" name=\"Name_First\" placeholder=\"First Name\" required>\n          </div>\n          <div class=\"input-group\">\n            <label for=\"consult_last_name\">Last Name *</label>\n            <input type=\"text\" id=\"consult_last_name\" name=\"Name_Last\" placeholder=\"Last Name\" required>\n          </div>\n        </div>\n\n        <div class=\"form-row\">\n          <div class=\"input-group\">\n            <label for=\"consult_email\">Email Address *</label>\n            <input type=\"email\" id=\"consult_email\" name=\"Email\" placeholder=\"name@domain.com\" required>\n          </div>\n          <div class=\"input-group\">\n            <label for=\"consult_phone\">Phone Number *</label>\n            <input type=\"tel\" id=\"consult_phone\" name=\"PhoneNumber\" placeholder=\"+61 400 000 000\" required>\n          </div>\n        </div>\n\n        <!-- Video Platform Preference -->\n        <div class=\"input-group\">\n          <label>Preferred Video Call Platform *</label>\n          <div class=\"consult-platform-options\">\n            <label class=\"platform-option\">\n              <input type=\"radio\" name=\"video_platform\" value=\"Zoom\" checked required>\n              <span>Zoom</span>\n            </label>\n            <label class=\"platform-option\">\n              <input type=\"radio\" name=\"video_platform\" value=\"WhatsApp\" required>\n              <span>WhatsApp</span>\n            </label>\n            <label class=\"platform-option\">\n              <input type=\"radio\" name=\"video_platform\" value=\"FaceTime\" required>\n              <span>FaceTime</span>\n            </label>\n          </div>\n        </div>\n\n        <!-- Advice Topics -->\n        <div class=\"input-group\">\n          <label>Advice Needed On (Select all that apply) *</label>\n          <div class=\"consult-topics-grid\">\n            <label class=\"topic-checkbox\">\n              <input type=\"checkbox\" name=\"consult_topics\" value=\"Preparing my application\" checked>\n              <span>Preparing my application (audit &amp; profile boost)</span>\n            </label>\n            <label class=\"topic-checkbox\">\n              <input type=\"checkbox\" name=\"consult_topics\" value=\"Property Shortlisting\">\n              <span>Property shortlisting &amp; suburb feasibility</span>\n            </label>\n            <label class=\"topic-checkbox\">\n              <input type=\"checkbox\" name=\"consult_topics\" value=\"Securing a rental property\">\n              <span>Securing a rental in competitive conditions</span>\n            </label>\n            <label class=\"topic-checkbox\">\n              <input type=\"checkbox\" name=\"consult_topics\" value=\"Tenancy Issues\">\n              <span>Tenancy issues (rent increases, lease breaks, repairs)</span>\n            </label>\n          </div>\n          <div style=\"margin-top: 8px;\">\n            <input type=\"text\" id=\"consult_other_topic\" name=\"consult_other_topic\" placeholder=\"Other specific topic (optional)\">\n          </div>\n        </div>\n\n        <!-- Situation Details -->\n        <div class=\"input-group\">\n          <label for=\"consult_notes\">Situation Details &amp; Questions *</label>\n          <textarea id=\"consult_notes\" name=\"notes\" rows=\"3\" placeholder=\"Please outline your current situation, any past rejections, target suburbs/cities, and key questions for your advocate...\" required></textarea>\n        </div>\n\n        <!-- Service Agreement & Terms Container -->\n        <div class=\"consult-terms-container\">\n          <h4 class=\"terms-title\">Service Agreement &amp; The Fine Print</h4>\n          <div class=\"terms-scroll-box\">\n            <p><strong>Parties &amp; Purpose:</strong> This Service Agreement is made between Your Home Hunter Pty Ltd (ACN 700 927 000, \"YHH\") and the Client named above. The Client engages YHH to provide independent tenancy consultation and advisory services on the terms set out herein.</p>\n            <p><strong>Advice Scope:</strong> The Client acknowledges that YHH bases its guidance on the Client's stated requirements and documentation detailed in this form. Should those requirements materially change and YHH is required to provide additional advice, an additional fee will be payable by the Client.</p>\n            <p><strong>Payment &amp; Scheduling:</strong> Consultations must be paid in full upfront prior to appointment confirmation. A minimum of 48 hours notice is required for scheduling or rescheduling appointments.</p>\n            <p><strong>Limitations of Liability:</strong> To the maximum extent permitted by Australian law, YHH's total liability arising out of or in connection with this Agreement is strictly limited to the aggregate value of Fees paid by the Client. Neither Party will be liable for indirect, incidental, special or consequential losses.</p>\n            <p><strong>Mutual Respect &amp; Code of Conduct:</strong> YHH is committed to supporting a culture of respect and well-being for our employees. We treat our clients with courtesy and respect and expect the same in return. Rude, disparaging remarks or bullying behaviour will not be tolerated. YHH reserves the right to terminate an engagement should this occur, with no refund payable.</p>\n            <p><strong>Governing Law:</strong> This Agreement is governed by the laws of the State of Victoria, Australia.</p>\n          </div>\n\n          <div class=\"terms-acceptance-box\">\n            <label class=\"terms-checkbox-label\">\n              <input type=\"checkbox\" id=\"consult_terms_accept\" required>\n              <span><strong>I have read, understood, and accept the terms and conditions of this Service Agreement *</strong></span>\n            </label>\n          </div>\n\n          <div class=\"form-row\" style=\"margin-top: 12px;\">\n            <div class=\"input-group\" style=\"margin-bottom: 0;\">\n              <label for=\"consult_signature\">Client Digital Signature (Full Name) *</label>\n              <input type=\"text\" id=\"consult_signature\" placeholder=\"Type your full legal name\" required>\n            </div>\n            <div class=\"input-group\" style=\"margin-bottom: 0;\">\n              <label for=\"consult_date\">Agreement Date</label>\n              <input type=\"text\" id=\"consult_date\" value=\"20-Sep-2026\" readonly style=\"background: #f8fafc; color: var(--text-muted);\">\n            </div>\n          </div>\n        </div>\n\n        <!-- Upfront Fee Summary Box -->\n        <div class=\"consult-fee-box\">\n          <div class=\"fee-row total\">\n            <strong>Consultation fee (60 minutes, inc. GST):</strong>\n            <strong>$165.00 AUD</strong>\n          </div>\n          <p class=\"fee-subtext\">Includes GST. After you submit this request, choose a time on <a href=\"https://calendar.google.com/calendar/u/0/appointments/schedules/AcZssZ2_cMxdfUojr153utSiTOByBuvddRpqBLdrqxksB8MPqO4UYEFzoJAKf0pyiJb2e_fZn0DvDBsC\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"gcal-consult-link\">Brit's calendar</a>. We will email your invoice payment link.</p>\n        </div>\n\n        <div class=\"form-privacy-block\">\n          <p class=\"form-collection-notice\">\n            <small>YHH Pty Ltd (Your Home Hunter) collects personal information to book and deliver your tenancy consultation. Details are handled under the <em>Privacy Act 1988</em> (Cth) and Australian Privacy Principles. Read our <button type=\"button\" class=\"link-style\" data-modal-target=\"collectionNoticeModal\">Privacy Collection Notice</button> (APP&nbsp;5) and <button type=\"button\" class=\"link-style\" data-modal-target=\"privacyDialog\">Privacy Policy</button>. We never sell your data.</small>\n          </p>\n          <label class=\"privacy-consent-label\">\n            <input type=\"checkbox\" name=\"privacyConsent\" class=\"privacy-consent-checkbox\" value=\"yes\" required>\n            <span>I have read and understand the Privacy Collection Notice and Privacy Policy *</span>\n          </label>\n        </div>\n\n        <button type=\"submit\" class=\"btn btn-primary btn-block\" style=\"padding: 14px; font-size: 1rem; margin-top: 10px;\">Accept Terms &amp; Book Consultation ($165.00 AUD inc. GST) &rarr;</button>\n        <p id=\"consult-form-status\" style=\"font-size: 0.9rem; margin-top: 10px; font-weight: 500; text-align: center;\"></p>\n      </form>\n\n      <!-- Confirmation Screen -->\n      <div id=\"consult-success-view\" class=\"wishlist-success-view\" style=\"display: none;\">\n        <div class=\"success-icon-badge\">&#10003;</div>\n        <h3>Consultation Brief Received &amp; Agreement Signed!</h3>\n        <p>Thank you. Your service agreement and consultation details have been logged securely with our advocacy team.</p>\n        <div class=\"success-summary-box\">\n          <p><strong>Next Steps:</strong></p>\n          <ul style=\"text-align: left; margin: 12px 0 16px 20px; font-size: 0.9rem; color: var(--text-dark);\">\n            <li>Your consultation booking reference has been created.</li>\n            <li>We will email your invoice payment link ($165 AUD inc. GST). Choose your time on Brit's calendar below.</li>\n            <li>Your advocate will examine your submitted details and prepare tailored guidance prior to your session.</li>\n          </ul>\n        </div>\n        <div class=\"success-calendar-cta-box\" style=\"margin: 18px 0; padding: 16px; background: #f0fdf4; border: 1px solid #bbf7d0; border-radius: var(--radius); text-align: center;\">\n          <h4 style=\"color: #065f46; margin: 0 0 6px; font-size: 1.05rem;\">📅 Choose Your 60-Minute Consultation Time</h4>\n          <p style=\"font-size: 0.9rem; color: #047857; margin: 0 0 12px;\">Lock in your preferred date and time on Brit's calendar:</p>\n          <a href=\"https://calendar.google.com/calendar/u/0/appointments/schedules/AcZssZ2_cMxdfUojr153utSiTOByBuvddRpqBLdrqxksB8MPqO4UYEFzoJAKf0pyiJb2e_fZn0DvDBsC\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"btn btn-primary gcal-consult-link\" id=\"consult-gcal-btn\" style=\"padding: 12px 24px; text-decoration: none; display: inline-block;\">\n            Select a time with Brit &rarr;\n          </a>\n          <p style=\"font-size: 0.8rem; color: #047857; margin: 8px 0 0;\">Opens Google Workspace Appointment Scheduling in a secure tab.</p>\n        </div>\n\n        <p style=\"font-size: 0.85rem; color: var(--text-muted); margin-top: 12px; text-align: center;\">\n          Have a quick question about your brief before the call? <a href=\"#\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"link-style whatsapp-consult-link\" id=\"consult-wa-link\">Chat directly on WhatsApp &rarr;</a>\n        </p>\n\n        <div class=\"modal-footer-row\" style=\"display: flex; gap: 12px; justify-content: center; margin-top: 20px;\">\n          <button type=\"button\" class=\"btn btn-outline\" data-modal-close>Done &amp; Close</button>\n        </div>\n      </div>\n\n      <div class=\"modal-footer-row\" style=\"display: flex; justify-content: space-between; align-items: center; margin-top: 16px; padding-top: 14px; border-top: 1px solid var(--border);\">\n        <a href=\"tel:1800666944\" class=\"btn btn-outline btn-sm\">Direct Phone: 1800 666 944</a>\n        <button type=\"button\" class=\"btn btn-outline btn-sm\" data-modal-close>Close</button>\n      </div>\n    </div>\n  </dialog>",
  "consultDetailsModal":  "<dialog id=\"consultDetailsModal\">\n    <div class=\"dialog-body\">\n      <button type=\"button\" class=\"modal-close-btn\" data-modal-close aria-label=\"Close dialog\">&times;</button>\n      <header>\n        <span class=\"tier-label\">Advisory &amp; Tenancy Strategy</span>\n        <h2>Tenancy Consultation Service</h2>\n        <div class=\"service-meta-box\">\n          <div class=\"service-meta-grid\">\n            <div class=\"service-meta-item\">\n              <strong>Investment</strong>\n              $165 inc. GST\n            </div>\n            <div class=\"service-meta-item\">\n              <strong>Format</strong>\n              1-on-1 Phone / Video Call + Action Plan\n            </div>\n            <div class=\"service-meta-item\">\n              <strong>Booking Policy</strong>\n              Minimum 48 hours notice required\n            </div>\n            <div class=\"service-meta-item\">\n              <strong>Advocate Focus</strong>\n              100% Independent Tenant Advocacy\n            </div>\n          </div>\n        </div>\n      </header>\n      <main>\n        <section>\n          <h3>Targeted Strategic Advice For Renters</h3>\n          <p>\n            Whether you keep getting rejected in Australia's competitive rental markets, need an expert eye to audit your application before submitting, or are navigating a stressful tenancy dispute, our 1-on-1 consultation connects you directly with a tenant advocate.\n          </p>\n        </section>\n\n        <section>\n          <h3>What We Cover in Your Consultation</h3>\n          <div class=\"step-item\">\n            <h4>Application Portfolio &amp; Profile Audit</h4>\n            <p>We review your complete application dossier across 2Apply, Snug, Ignite, or paper forms. We pinpoint hidden red flags in your employment documentation, proof of funds, rental ledgers, and referee presentation that cause leasing agents to pass over your profile.</p>\n          </div>\n          <div class=\"step-item\">\n            <h4>Rejection Diagnosis &amp; Market Repositioning</h4>\n            <p>If you've been applying without success, we diagnose the bottlenecks such as rent-to-income affordability calculations, personal identification gaps, or submission delays to build an immediate, winning application strategy.</p>\n          </div>\n          <div class=\"step-item\">\n            <h4>Expat, Interstate &amp; Non-Standard Income Strategy</h4>\n            <p>Moving from interstate or overseas without Australian rental history? Self-employed, contracting, or living off savings? We advise you on the exact financial and character evidence property managers require to approve non-standard applicants.</p>\n          </div>\n          <div class=\"step-item\">\n            <h4>Tenancy Disputes, Rent Hikes &amp; Lease Negotiations</h4>\n            <p>Unbiased guidance on navigating excessive rent increase notices, negotiating lease transfers, ending fixed terms early without penalty, requesting urgent repairs, and preparing for state tenancy tribunals (VCAT, QCAT, ACAT, SACAT).</p>\n          </div>\n        </section>\n\n        <section>\n          <div class=\"notice-callout\">\n            <strong>Booking &amp; Scheduling Notice:</strong> All consultations require a minimum of 48 hours notice prior to scheduled time. Following your session, you will receive a written summary outlining our provided advice based on your unique circumstance.\n          </div>\n        </section>\n      </main>\n      <div class=\"modal-actions\">\n        <button type=\"button\" data-modal-target=\"consultBookingModal\" class=\"btn btn-primary\">Book Consultation</button>\n        <a href=\"tel:1800666944\" class=\"btn btn-outline\">Call 1800 666 944</a>\n        <button type=\"button\" class=\"btn btn-outline\" data-modal-close style=\"margin-left: auto;\">Close</button>\n      </div>\n    </div>\n  </dialog>",
  "inspectorNetworkModal":  "<dialog id=\"inspectorNetworkModal\">\n    <div class=\"dialog-body\">\n      <button type=\"button\" class=\"modal-close-btn\" data-modal-close aria-label=\"Close dialog\">&times;</button>\n      <header>\n        <span class=\"tier-label\">Ground Team &amp; Network</span>\n        <h2>Your Home Hunter Inspector Network</h2>\n        <div class=\"service-meta-box\">\n          <div class=\"service-meta-grid\">\n            <div class=\"service-meta-item\">\n              <strong>Role</strong>\n              Independent Field Property Inspector\n            </div>\n            <div class=\"service-meta-item\">\n              <strong>Locations</strong>\n              Melbourne, Brisbane, Canberra &amp; Adelaide\n            </div>\n            <div class=\"service-meta-item\">\n              <strong>Engagement</strong>\n              Flexible / Client-Driven Per-Inspection\n            </div>\n            <div class=\"service-meta-item\">\n              <strong>Focus</strong>\n              Objective Assessments &amp; Live Video Tours\n            </div>\n          </div>\n        </div>\n      </header>\n      <main>\n        <section>\n          <h3>About Our Inspector Team</h3>\n          <p>\n            Our inspector team brings a wide range of customer service and professional backgrounds, united by a genuine interest in property and helping people find the right place to call home.\n          </p>\n          <p style=\"margin-top: 10px;\">\n            Inspectors attend open-for-inspections and private appointments on behalf of our clients to evaluate potential properties for overall condition and suitability. Our clients receive honest, frank, and unbiased assessments covering both the highlights and any red flags.\n          </p>\n        </section>\n\n        <section>\n          <h3>What Our Inspectors Do</h3>\n          <div class=\"step-item\">\n            <h4>Physical Attendance On-Site</h4>\n            <p>Representing clients at scheduled viewings across Melbourne, Brisbane, Canberra, and Adelaide, arriving promptly to liaise with the leasing agent.</p>\n          </div>\n          <div class=\"step-item\">\n            <h4>Live Video Streaming &amp; 4K Walkthroughs</h4>\n            <p>Walking clients through properties via Zoom, FaceTime, or WhatsApp in real time, or capturing clear, steady high-definition video walkthroughs with live commentary.</p>\n          </div>\n          <div class=\"step-item\">\n            <h4>Condition &amp; Defect Examination</h4>\n            <p>Testing tap pressure, shower drainage, window locks, and power outlets; checking for damp or cupboard odours; evaluating storage, acoustic levels, and natural light orientation.</p>\n          </div>\n          <div class=\"step-item\">\n            <h4>Neighbourhood &amp; Street Evaluation</h4>\n            <p>Observing surrounding street noise, parking permit availability, building maintenance, and the overall feel of the local pocket.</p>\n          </div>\n        </section>\n\n        <section>\n          <h3>Join Our Inspector Network</h3>\n          <p>\n            We are always interested in connecting with passionate, detail-oriented individuals looking for flexible, part-time work. This opportunity is well suited to retirees, semi-retired professionals, or anyone with customer service experience, reliable transport, and a keen eye for property.\n          </p>\n          <div class=\"notice-callout\">\n            <strong>Key Requirements:</strong> Punctuality, excellent interpersonal skills, a valid driver's licence with reliable transport, and a smartphone capable of high-definition video calling.\n          </div>\n        </section>\n        <section id=\"inspector-application-section\" style=\"margin-top: 24px; padding-top: 20px; border-top: 1px solid var(--border);\">\n          <h3>Inspector Network Application</h3>\n          <p class=\"modal-subtext\" style=\"margin-bottom: 16px;\">Complete this brief questionnaire to apply. Wendy and our operations team will review your details and reach out directly.</p>\n\n          <form id=\"inspector-application-form\" class=\"lead-form\">\n            <div class=\"form-row\">\n              <div class=\"input-group\">\n                <label for=\"insp_first_name\">First Name *</label>\n                <input type=\"text\" id=\"insp_first_name\" name=\"Name_First\" placeholder=\"First Name\" required>\n              </div>\n              <div class=\"input-group\">\n                <label for=\"insp_last_name\">Last Name *</label>\n                <input type=\"text\" id=\"insp_last_name\" name=\"Name_Last\" placeholder=\"Last Name\" required>\n              </div>\n            </div>\n\n            <div class=\"form-row\">\n              <div class=\"input-group\">\n                <label for=\"insp_email\">Email Address *</label>\n                <input type=\"email\" id=\"insp_email\" name=\"Email\" placeholder=\"name@domain.com\" required>\n              </div>\n              <div class=\"input-group\">\n                <label for=\"insp_phone\">Phone Number *</label>\n                <input type=\"tel\" id=\"insp_phone\" name=\"PhoneNumber\" placeholder=\"+61 400 000 000\" required>\n              </div>\n            </div>\n\n            <div class=\"input-group\">\n              <label for=\"insp_suburb\">Home Suburb &amp; State *</label>\n              <input type=\"text\" id=\"insp_suburb\" name=\"suburb_travel\" placeholder=\"Where do you live &amp; how far are you prepared to travel? (e.g. Richmond VIC, within 15km)\" list=\"yhh-au-suburbs-list\" autocomplete=\"address-level2\" required>\n            </div>\n\n            <div class=\"input-group\">\n              <label for=\"insp_background\">Overview of Your Background *</label>\n              <textarea id=\"insp_background\" name=\"background\" rows=\"3\" placeholder=\"Please provide a brief overview of your professional background (customer service, real estate, trade, or general professional experience)...\" required></textarea>\n            </div>\n\n            <div class=\"input-group\">\n              <label for=\"insp_availability\">What Is Your Availability? *</label>\n              <textarea id=\"insp_availability\" name=\"availability\" rows=\"2\" placeholder=\"Generally when would you be available to attend inspections? (e.g. Saturdays 9am-1pm, weekdays after 3pm, flexible weekdays)...\" required></textarea>\n            </div>\n\n            <div class=\"form-privacy-block\">\n              <p class=\"form-collection-notice\">\n                <small>YHH Pty Ltd (Your Home Hunter) collects personal information to assess inspector network applications. Details are handled under the <em>Privacy Act 1988</em> (Cth) and Australian Privacy Principles. Read our <button type=\"button\" class=\"link-style\" data-modal-target=\"collectionNoticeModal\">Privacy Collection Notice</button> (APP&nbsp;5) and <button type=\"button\" class=\"link-style\" data-modal-target=\"privacyDialog\">Privacy Policy</button>. We never sell your data.</small>\n              </p>\n              <label class=\"privacy-consent-label\">\n                <input type=\"checkbox\" name=\"privacyConsent\" class=\"privacy-consent-checkbox\" value=\"yes\" required>\n                <span>I have read and understand the Privacy Collection Notice and Privacy Policy *</span>\n              </label>\n            </div>\n\n            <button type=\"submit\" class=\"btn btn-primary btn-block\" style=\"padding: 14px; font-size: 1rem; margin-top: 8px;\">Submit Inspector Application </button>\n            <p id=\"insp-form-status\" style=\"font-size: 0.9rem; margin-top: 10px; font-weight: 500; text-align: center;\"></p>\n          </form>\n\n          <div id=\"inspector-success-view\" class=\"wishlist-success-view\" style=\"display: none;\">\n            <div class=\"success-icon-badge\">&#10003;</div>\n            <h3>Application Received!</h3>\n            <p>Thank you for your interest in joining the Your Home Hunter Inspector Network.</p>\n            <div class=\"success-summary-box\">\n              <p><strong>What Happens Next:</strong></p>\n              <ul style=\"text-align: left; margin: 12px 0 16px 20px; font-size: 0.9rem; color: var(--text-dark);\">\n                <li>Our team will review your suburb coverage, background, and weekly availability.</li>\n                <li>If there is a match for upcoming inspection volume in your area, we will contact you for an introductory phone briefing.</li>\n                <li>Shortlisted inspectors undergo a brief virtual orientation before attending client viewings.</li>\n              </ul>\n            </div>\n            <div class=\"modal-footer-row\" style=\"display: flex; gap: 12px; justify-content: center; margin-top: 20px;\">\n              <button type=\"button\" class=\"btn btn-primary\" data-modal-close>Done &amp; Close</button>\n            </div>\n          </div>\n        </section>\n      </main>\n      <div class=\"modal-actions\" style=\"margin-top: 16px;\">\n        <a href=\"tel:1800666944\" class=\"btn btn-outline\">Direct Phone: 1800 666 944</a>\n        <button type=\"button\" class=\"btn btn-outline\" data-modal-close style=\"margin-left: auto;\">Close</button>\n      </div>\n    </div>\n  </dialog>",
  "caseStudiesModal":  "<dialog id=\"caseStudiesModal\">\n    <div class=\"dialog-body\">\n      <button type=\"button\" class=\"modal-close-btn\" data-modal-close aria-label=\"Close dialog\">&times;</button>\n      <header>\n        <span class=\"tier-label\">Verified Case Studies &amp; Outcomes</span>\n        <h2>Real Client Stories: Overcoming The Rental Squeeze</h2>\n        <div class=\"service-meta-box\">\n          <div class=\"service-meta-grid\">\n            <div class=\"service-meta-item\">\n              <strong>Track Record</strong>\n              95%+ Placement Success Rate\n            </div>\n            <div class=\"service-meta-item\">\n              <strong>Client Types</strong>\n              Expats, First-Timers, Families, Self-Employed\n            </div>\n            <div class=\"service-meta-item\">\n              <strong>Network Edge</strong>\n              Pre-Market &amp; Off-Market Access\n            </div>\n            <div class=\"service-meta-item\">\n              <strong>Average Rating</strong>\n              ★★★★★ 4.9 from 204 Google reviews\n            </div>\n          </div>\n        </div>\n      </header>\n      <main>\n        <section>\n          <h3>How Independent Advocacy Changes Outcomes</h3>\n          <p>\n            When rental vacancy drops below 1%, online platforms become automated lotteries. Here is how our personalized advocacy, off-market agency relationships, and strategic packaging helped real clients secure homes in Australia's tightest markets.\n          </p>\n        </section>\n\n        <section>\n          <div class=\"step-item\">\n            <h4>1. The International Expat Family &bull; Hilda &amp; Otto (Germany to Brisbane)</h4>\n            <p><strong>The Challenge:</strong> Relocating with young children and a strict university semester deadline. Faced severe confusion with Australian portal requirements and had zero local credit history.</p>\n            <p style=\"margin-top: 6px;\"><strong>The Solution:</strong> YHH took over all agency liaison, arranged cross-time-zone video inspections, uncovered an unadvertised off-market home in Ashgrove, and secured full lease approval prior to their arrival.</p>\n          </div>\n\n          <div class=\"step-item\">\n            <h4>2. First-Time Student Renter &bull; Michelle &amp; Lea (NSW to Melbourne)</h4>\n            <p><strong>The Challenge:</strong> A young university student with excellent personal character but no prior rental ledger. Encountered 60+ attendee inspection queues and rampant informal rent bidding ($50-$80 over ask).</p>\n            <p style=\"margin-top: 6px;\"><strong>The Solution:</strong> Bypassed public portal congestion by tapping our agency partner network in South Melbourne to secure a quality apartment within budget ahead of semester.</p>\n          </div>\n\n          <div class=\"step-item\">\n            <h4>3. Self-Employed &amp; Touring Creatives &bull; Miranda &amp; Steve</h4>\n            <p><strong>The Challenge:</strong> Touring internationally producing an arena concert show with a newborn baby. Lacked a fixed address for 6 months and had non-standard business income that automated portals immediately flag as high-risk.</p>\n            <p style=\"margin-top: 6px;\"><strong>The Solution:</strong> Prepared a comprehensive financial and character dossier, addressed property manager questions in real time, and secured landlord approval with zero delays.</p>\n          </div>\n\n          <div class=\"step-item\">\n            <h4>4. Accessible Home Renovation Decant &bull; Margaret (Canberra)</h4>\n            <p><strong>The Challenge:</strong> Needed temporary accessible, furnished accommodation in a highly competitive inner Canberra suburb while her own home was upgraded to accessibility standards.</p>\n            <p style=\"margin-top: 6px;\"><strong>The Solution:</strong> Arranged private walkthroughs at her own pace and successfully negotiated flexible lease commencement and duration terms with the property owner.</p>\n          </div>\n\n          <div class=\"step-item\">\n            <h4>5. Medical Professional Hospital Relocation &bull; Kristian &amp; Stefanie</h4>\n            <p><strong>The Challenge:</strong> European doctors starting hospital appointments in Brisbane on fixed dates with a young daughter. Faced severe housing shortages in hospital catchment suburbs.</p>\n            <p style=\"margin-top: 6px;\"><strong>The Solution:</strong> A dedicated YHH advocate accompanied Stefanie on arrival for private viewings, validated property safety and commute times, and settled the family in just a few short weeks.</p>\n          </div>\n        </section>\n\n        <section>\n          <div class=\"notice-callout\">\n            <strong>Ready to secure your next home?</strong> Every search is customized to your unique circumstances, timeline, and budget.\n          </div>\n        </section>\n      </main>\n      <div class=\"modal-actions\">\n        <button type=\"button\" data-modal-target=\"enquiryDialog\" class=\"btn btn-primary\">Talk to Us</button>\n        <button type=\"button\" data-modal-target=\"searchDialog\" class=\"btn btn-outline\">Request a Search</button>\n        <button type=\"button\" class=\"btn btn-outline\" data-modal-close style=\"margin-left: auto;\">Close</button>\n      </div>\n    </div>\n  </dialog>",
  "termsDialog":  "<dialog id=\"termsDialog\">\n    <div class=\"dialog-body\">\n      <button type=\"button\" class=\"modal-close-btn\" data-modal-close aria-label=\"Close dialog\">&times;</button>\n      <header>\n        <h2>Website Terms and Conditions</h2>\n        <div class=\"meta-info\">\n          <p><strong>Effective Date:</strong> 20 September 2026</p>\n          <p><strong>Operating Entity:</strong> Your Home Hunter (YHH PTY LTD) ABN 62 700 927 000</p>\n          <p><strong>Website:</strong> <a href=\"https://www.yourhomehunter.com.au\" target=\"_blank\" rel=\"noopener noreferrer\">www.yourhomehunter.com.au</a></p>\n        </div>\n      </header>\n      <main>\n        <section>\n          <p>\n            By using this website you agree to be bound by the terms and conditions set out on this webpage. If you do not accept these terms and conditions, you must refrain from using this website. This website is owned and operated by Your Home Hunter (YHH PTY LTD) ABN 62 700 927 000 (referred to in these terms and conditions as &lsquo;we&rsquo;, &lsquo;us&rsquo;, or &lsquo;our&rsquo;).\n          </p>\n        </section>\n\n        <section>\n          <h3>Intellectual Property</h3>\n          <p>\n            Unless otherwise indicated, all materials used on this website (including text, graphics, logos, icons, sound recordings and software) are subject to copyright, trademark or other intellectual property rights that are owned or licensed by us. You may only access and use these materials for non-commercial or personal use, except to the extent permitted by law or where you have received prior written approval from us.\n          </p>\n        </section>\n\n        <section>\n          <h3>Liability</h3>\n          <p>\n            We make no warranties or representations about this website or any of its content and will not be responsible to you or any third party for any direct or consequential loss suffered in connection with the use of this website. To the maximum extent permitted by law, we exclude any liability that may arise due to your use of our website and/or the information or materials contained on it. You agree to indemnify us for any loss or liability arising out of your use of this site.\n          </p>\n        </section>\n\n        <section>\n          <h3>External Links</h3>\n          <p>\n            Our website may contain links to websites operated by third parties. Those links are provided for convenience and may not remain current or be maintained. Unless expressly stated otherwise, we do not endorse and are not responsible for the content on those linked websites and have no control over or rights in those linked websites.\n          </p>\n        </section>\n\n        <section>\n          <h3>Updates</h3>\n          <p>\n            We may change these terms and conditions at any time by updating this webpage and your continued use of the website following such update will represent an agreement by you to be bound by the terms and conditions as amended.\n          </p>\n        </section>\n\n        <section>\n          <h3>Privacy</h3>\n          <p>\n            These terms and conditions also include our <button type=\"button\" class=\"link-style\" data-modal-target=\"privacyDialog\">Privacy Policy</button> that can be accessed by clicking the link on this page.\n          </p>\n        </section>\n\n        <section>\n          <h3>Jurisdiction</h3>\n          <p>\n            Your use of the website and these terms and conditions are governed by the laws of VIC, Australia.\n          </p>\n        </section>\n      </main>\n      <button type=\"button\" class=\"btn btn-primary\" data-modal-close style=\"margin-top: 24px;\">Close</button>\n    </div>\n  </dialog>",
  "privacyDialog":  "<dialog id=\"privacyDialog\">\n    <div class=\"dialog-body\">\n      <button type=\"button\" class=\"modal-close-btn\" data-modal-close aria-label=\"Close dialog\">&times;</button>\n      <header>\n        <h2>Privacy Policy</h2>\n        <div class=\"meta-info\">\n          <p><strong>Effective Date:</strong> 14 September 2026</p>\n          <p><strong>Operating Entity:</strong> YHH Pty Ltd (ACN 700 927 000) trading as Your Home Hunter</p>\n          <p><strong>Website:</strong> <a href=\"https://www.yourhomehunter.com.au\" target=\"_blank\" rel=\"noopener noreferrer\">www.yourhomehunter.com.au</a></p>\n        </div>\n      </header>\n      <main>\n        <section>\n          <h3>Introduction and Purpose</h3>\n          <p>YHH Pty Ltd trading as Your Home Hunter (&ldquo;we&rdquo;, &ldquo;us&rdquo;, or &ldquo;our&rdquo;) provides renters&rsquo; advocacy, property search, video walkthrough inspection, and tenancy consulting services across Australia.</p>\n          <p>We respect your privacy and are committed to protecting personal and sensitive information in accordance with the <em>Privacy Act 1988</em> (Cth) and the Australian Privacy Principles (APPs). This Privacy Policy explains what information we collect, how we handle and protect it, who we disclose it to, and your rights regarding your personal records.</p>\n        </section>\n\n        <section>\n          <h3>Contact Details &amp; Privacy Officer</h3>\n          <p>If you have questions about this policy, wish to request access to or correction of your information, or want to make a complaint, please contact:</p>\n          <address>\n            <p><strong>Entity:</strong> YHH Pty Ltd trading as Your Home Hunter<br>\n            <strong>Privacy Officer Email:</strong> <a href=\"mailto:info@yourhomehunter.com.au\">info@yourhomehunter.com.au</a><br>\n            <strong>Telephone:</strong> <a href=\"tel:1800666944\">1800 666 944</a><br>\n            <strong>Postal Address:</strong> PO Box 179, Ringwood East, Vic 3135, Australia<br>\n            <strong>Registered Office:</strong> C/- Judge Accountants, Suite 2, Level 3, 50 Belmore Street, Penrith NSW 2750</p>\n          </address>\n        </section>\n\n        <section>\n          <h3>Personal Information We Collect</h3>\n          <p>Because we advocate for tenants and submit rental applications on their behalf, we collect personal and sensitive information directly from clients, including:</p>\n          <ul>\n            <li><strong>Identity Documentation:</strong> Full legal names, dates of birth, residential addresses, contact telephone numbers, email addresses, emergency contacts, and copies of government-issued identity documents (passports, driver licences, citizenship records).</li>\n            <li><strong>Financial &amp; Employment Records:</strong> Payslips, employment agreements, accountant verification letters, proof of funds, and bank statements showing living allowances.</li>\n            <li><strong>Tenancy Background:</strong> Rental ledgers, past landlord or agent reference contacts, personal and professional character references, pet profiles, and detailed housing criteria.</li>\n            <li><strong>Payment Details:</strong> Direct debit and credit card details collected via our PCI-compliant payment gateway (Square and Pinch Payments) and banking channels (National Australia Bank). We do not store full credit card numbers on our internal servers.</li>\n            <li><strong>Website &amp; Technical Data:</strong> IP addresses, browser types, device identifiers, and site usage data collected through our website host and Google Analytics (when enabled).</li>\n          </ul>\n        </section>\n\n        <section>\n          <h3>How We Collect Information</h3>\n          <p>We collect personal information primarily directly from you when you:</p>\n          <ul>\n            <li>Complete our online inquiry, contact, search brief, or Full Service Package forms on this website (or via DocuSign / Stripe when those links are provided).</li>\n            <li>Sign our Client Service Agreement.</li>\n            <li>Transmit identity, financial, and employment records via email, file sharing, or form upload.</li>\n            <li>Communicate with our advocates and inspectors by email, phone, or instant messaging.</li>\n          </ul>\n        </section>\n\n        <section>\n          <h3>Why We Collect and How We Use Your Information</h3>\n          <p>We collect, hold, and use your information exclusively to:</p>\n          <ul>\n            <li>Assess your property search brief, criteria, and budget.</li>\n            <li>Inspect properties and deliver detailed video walkthrough reports.</li>\n            <li>Prepare, complete, and submit competitive residential tenancy applications on your behalf.</li>\n            <li>Advocate with real estate agents, property managers, and private landlords.</li>\n            <li>Review lease documents and tenancy agreements.</li>\n            <li>Invoice and process service fees.</li>\n            <li>Comply with statutory tax, corporate, and accounting record-keeping obligations under Australian law.</li>\n          </ul>\n        </section>\n\n        <section>\n          <h3>Disclosures to Third Parties &amp; Rental Portals</h3>\n          <p>To deliver our advocacy services, we disclose your documentation to third parties strictly on your instructions:</p>\n          <ul>\n            <li><strong>Real Estate Agents &amp; Landlords:</strong> We provide tenancy applications, identity documents, financial verifications, and references directly to prospective agents and property owners.</li>\n            <li><strong>Online Tenancy Application Portals:</strong> Many Australian leasing agencies mandate application lodgement through third-party platforms, including 2Apply, Snug, Ignite (<a href=\"https://www.realestate.com.au\" target=\"_blank\" rel=\"noopener noreferrer\">realestate.com.au</a>), and TenantApp. When we submit an application for you, your data is processed through those platforms subject to their independent privacy policies and terms of service. <em>Note:</em> We cannot control or alter data retention and destruction schedules operated independently by these external portals.</li>\n            <li><strong>Operational Cloud Suppliers:</strong> We use secure software platforms to operate our business, including Google Workspace, Zoho CRM / Forms, Xero, and Pinch Payments.</li>\n            <li><strong>Legal Requirements:</strong> Where required or authorised by Australian law, court order, or regulatory body.</li>\n          </ul>\n        </section>\n\n        <section>\n          <h3>Overseas Disclosures &amp; International Clients</h3>\n          <p>Our business operates within Australia. However:</p>\n          <ul>\n            <li><strong>Cloud Infrastructure:</strong> Cloud platforms we use (such as Google Workspace and Zoho) may store or replicate data across secure data centres located overseas, including in the United States.</li>\n            <li><strong>Inbound Relocations:</strong> We routinely represent expatriates and international clients relocating to Australia. By engaging our services and submitting your application documents from outside Australia, you consent to the cross-border transfer, storage, and processing of your personal data within Australia to enable the sourcing and securing of an Australian rental property.</li>\n          </ul>\n        </section>\n\n        <section>\n          <h3>Data Retention, Storage, and Secure Destruction</h3>\n          <ul>\n            <li><strong>Application &amp; Verification Documents:</strong> Highly sensitive identification documents (passports, driver licences), bank statements, and payslips held directly on our internal storage are permanently deleted or de-identified within thirty (30) days after placement, completion, or formal termination of your service agreement.</li>\n            <li><strong>Statutory Records:</strong> Executed agreements, tax invoices, and accounting records are maintained for five (5) to seven (7) years as required under the <em>Corporations Act 2001</em> (Cth) and Australian taxation legislation.</li>\n            <li><strong>Security Controls:</strong> We implement TLS/HTTPS encryption on web forms, role-based access control, and multi-factor authentication (MFA) across our digital workspaces to protect data from loss, misuse, or unauthorised access.</li>\n          </ul>\n        </section>\n\n        <section>\n          <h3>Website Cookies and Analytics</h3>\n          <p>Our website uses cookies and tracking technologies:</p>\n          <ul>\n            <li><strong>Strictly Necessary Cookies:</strong> Essential for page navigation, security, and the technical operation of our website hosting platform.</li>\n            <li><strong>Performance &amp; Analytics Cookies:</strong> Deployed via Google Analytics and Google Tag Manager to assess site usage, visitor volume, and interaction trends. These cookies collect anonymised diagnostic and traffic data.</li>\n          </ul>\n          <p>You can disable or delete cookies at any time via your browser settings.</p>\n        </section>\n\n        <section>\n          <h3>Access, Corrections, and Complaints</h3>\n          <p><strong>Access and Correction:</strong> You may request access to the personal information we hold about you or ask us to correct inaccurate, outdated, or incomplete records (in line with APPs 12 and 13) by emailing <a href=\"mailto:info@yourhomehunter.com.au\">info@yourhomehunter.com.au</a>. We will respond within thirty (30) days without charging a fee for lodging the request.</p> \n          <p><strong>Internal Complaints Process:</strong> If you have concerns about how we have handled your personal information:</p>\n          <ol>\n            <li>Submit your complaint in writing to <a href=\"mailto:info@yourhomehunter.com.au\">info@yourhomehunter.com.au</a>.</li>\n            <li>We will confirm receipt within five (5) business days and conduct an internal review.</li>\n            <li>We will provide a formal written resolution within thirty (30) calendar days.</li>\n          </ol>\n          <p><strong>External Escalation (OAIC):</strong> If you are dissatisfied with our response, you may lodge a complaint with the Office of the Australian Information Commissioner (OAIC):</p>\n          <address>\n            <p><strong>Website:</strong> <a href=\"https://www.oaic.gov.au\" target=\"_blank\" rel=\"noopener noreferrer\">www.oaic.gov.au</a><br>\n            <strong>Phone:</strong> <a href=\"tel:1300363992\">1300 363 992</a><br>\n            <strong>Post:</strong> GPO Box 5218, Sydney NSW 2001</p>\n          </address>\n        </section>\n\n        <section>\n          <h3>Updates to this Policy</h3>\n          <p>We may revise this Privacy Policy periodically to reflect operational, commercial, or regulatory changes. The latest version will always be published on our website with the corresponding Effective Date.</p>\n        </section>\n      </main>\n      <button type=\"button\" class=\"btn btn-primary\" data-modal-close style=\"margin-top: 24px;\">Close</button>\n    </div>\n  </dialog>",
  "collectionNoticeModal":  "<dialog id=\"collectionNoticeModal\">\n    <div class=\"dialog-body\">\n      <button type=\"button\" class=\"modal-close-btn\" data-modal-close aria-label=\"Close dialog\">&times;</button>\n      <header>\n        <span class=\"tier-label\">Statutory Compliance</span>\n        <h2>Privacy Collection Notice</h2>\n        <div class=\"meta-info\">\n          <p><strong>Standards:</strong> AU APP 5 &bull; GDPR Art. 13 &bull; US State Privacy Laws</p>\n          <p><strong>Entity:</strong> YHH Pty Ltd (ACN 700 927 000) trading as Your Home Hunter</p>\n          <p><strong>Contact:</strong> PO Box 179, Ringwood East, Vic 3135 &bull; <a href=\"mailto:info@yourhomehunter.com.au\">info@yourhomehunter.com.au</a> &bull; <a href=\"tel:1800666944\">1800 666 944</a></p>\n        </div>\n      </header>\n      <main>\n        <section>\n          <h3>Who We Are</h3>\n          <p>Your personal data is collected by <strong>YHH Pty Ltd (ACN 700 927 000)</strong>, trading as <strong>Your Home Hunter</strong> (PO Box 179, Ringwood East, Vic 3135 | <a href=\"mailto:info@yourhomehunter.com.au\">info@yourhomehunter.com.au</a>).</p>\n        </section>\n\n        <section>\n          <h3>Purpose &amp; Legal Basis</h3>\n          <p>We collect your identity records, contact details, financial verifications, and tenancy histories to assess your rental brief, conduct property inspections, and prepare and lodge tenancy applications on your behalf. Under GDPR Art. 6, our lawful bases are the performance of our advocacy agreement and our legitimate interests in delivering tenancy consulting services.</p>\n        </section>\n\n        <section>\n          <h3>Disclosures &amp; International Transfers</h3>\n          <p>To progress your rental applications, your materials may be submitted to prospective property managers, private landlords, and digital tenancy portals (including 2Apply, Snug, and Ignite), as well as secure operational cloud subprocessors (Zoho CRM, Google Workspace, Xero, Pinch Payments). For clients outside Australia (EEA/UK/US), your information will be transferred to and securely processed within Australia pursuant to standard contractual clauses or your explicit contractual instruction.</p>\n        </section>\n\n        <section>\n          <h3>US Notice &amp; No Sale of Data</h3>\n          <p>We collect personal identifiers and commercial rental information solely to deliver our advocacy and inspection services. We do not sell, rent, or share personal data for monetary value or cross-context behavioral advertising.</p>\n        </section>\n\n        <section>\n          <h3>Consequences of Non-Collection</h3>\n          <p>Supplying your details is voluntary; however, failure to provide mandatory identity and financial verification may prevent us from evaluating properties, attending inspections, or lodging competitive tenancy applications on your behalf.</p>\n        </section>\n\n        <section>\n          <h3>Retention, Rights &amp; Access</h3>\n          <p>Sensitive identity and income records are securely destroyed or de-identified within thirty (30) days of service completion. Depending on your jurisdiction, you have the right to access, rectify, restrict, or erase your personal information, or lodge a complaint with the OAIC (Australia), your local EU Data Protection Authority, or your US State Attorney General. For complete details, see our full <button type=\"button\" class=\"link-style\" data-modal-target=\"privacyDialog\">Privacy Policy</button>.</p>\n        </section>\n      </main>\n      <div class=\"modal-actions\" style=\"margin-top: 24px;\">\n        <button type=\"button\" class=\"btn btn-primary\" data-modal-close>I Understand &amp; Close</button>\n      </div>\n    </div>\n  </dialog>"
};
